import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { AuthFrame, BackToSignIn } from "@/components/auth-frame"
import { api } from "../../api.ts"
import { base, realmKey } from "../../config.ts"
import { t } from "../i18n.ts"

// Asking for a link to set a new password. It says the same whether the
// email has an account or not: nobody learns who has one.
export function ForgotPasswordPage() {
  const [sent, setSent] = useState(false)
  const [busy, setBusy] = useState(false)
  if (sent) return <AuthFrame tone="success" title={t("checkEmail")} hint={t("linkSent")} footer={<BackToSignIn />} />
  return (
    <AuthFrame title={t("forgotPassword")} hint={t("forgotHint")} footer={<BackToSignIn />}>
      <form
        onSubmit={async (e) => {
          e.preventDefault()
          const email = String(new FormData(e.currentTarget).get("email"))
          const identity = api.identity[realmKey] as { forgotPassword?: (r: { email: string; redirect?: string }) => Promise<void> }
          setBusy(true)
          try {
            await identity.forgotPassword?.({ email, redirect: `${base}reset-password` })
          } finally {
            setBusy(false)
            setSent(true)
          }
        }}
      >
        <FieldGroup className="gap-5">
          <Field>
            <FieldLabel htmlFor="email">{t("email")}</FieldLabel>
            <Input id="email" name="email" type="email" autoComplete="email" className="h-11" required autoFocus />
          </Field>
          <Button type="submit" size="lg" className="w-full" disabled={busy}>
            {busy && <Spinner />}
            {t("sendLink")}
          </Button>
        </FieldGroup>
      </form>
    </AuthFrame>
  )
}
